    // Built via concat() rather than a literal so this test's own source
    // doesn't self-match its own trigger/definition-marker strings.
    let trigger = ["render_toon", "(&"].concat();
    let definition_marker = ["fn ", "render_toon", "("].concat();
    let bound_markers = [
        "?",
