/// Escape a scalar value for TOON row output.
///
/// Values containing `,` or `"` are quoted. Inside quotes `\` starts an escape, so `"` and `\` are written as `\"`
/// and `\\`. Unquoted values have no escape syntax and keep backslashes literally.
pub fn escape_value(v: &str) -> std::borrow::Cow<'_, str> {
    if v.is_empty() {
        return std::borrow::Cow::Borrowed(v);
    }

    let mut needs_quote = false;
    let mut escape_count = 0usize;
    let mut stripped_count = 0usize;
    for ch in v.chars() {
        match ch {
            ',' => needs_quote = true,
            '"' => {
                needs_quote = true;
                escape_count += 1;
            }
            '\\' => escape_count += 1,
            '\n' | '\r' => stripped_count += 1,
            _ => {}
        }
    }

    if !needs_quote && stripped_count == 0 {
        return std::borrow::Cow::Borrowed(v);
    }

    let capacity = v.len() - stripped_count + if needs_quote { escape_count + 2 } else { 0 };
    let mut out = String::with_capacity(capacity);
    if needs_quote {
        out.push('"');
    }
    for ch in v.chars() {
        match ch {
            '\n' | '\r' => {}
            '"' | '\\' if needs_quote => {
                out.push('\\');
                out.push(ch);
            }
            _ => out.push(ch),
        }
    }
    if needs_quote {
        out.push('"');
    }
    std::borrow::Cow::Owned(out)
}

